'use strict';
const $=id=>document.getElementById(id);
let state,masterBase64,revision,purchaseFormat='',pending=[],editingId=null,deletingId=null,busy=false,blocked=false,saving=false;
const sessionResponse=await fetch('/api/me',{cache:'no-store'});
if(!sessionResponse.ok){location.assign('/');throw Error('Inicia sesión.');}
const sessionData=await sessionResponse.json();Object.assign(TIP,sessionData.catalogos.compras.TIP);Object.assign(CAT,sessionData.catalogos.compras.CAT);Object.assign(SUB,sessionData.catalogos.compras.SUB);const appInfo=sessionData.app,currentUser=sessionData.user,canReadPurchases=currentUser.modulos.includes('compras'),canEdit=canReadPurchases&&['superadmin','auxti','compras','alta'].includes(currentUser.role),canDelete=['superadmin','auxti'].includes(currentUser.role),canLoadMasters=currentUser.modulos.includes('cargar_maestro'),canEditImages=['superadmin','auxti'].includes(currentUser.role)&&currentUser.modulos.includes('imagenes');
async function load(){const response=await fetch('/api/catalogo',{cache:'no-store'});if(!response.ok)throw Error('No se pudo conectar al servidor. Recarga la página.');const data=await response.json();state=validateState(data.state);masterBase64=data.master;revision=data.revision;purchaseFormat=data.formatoMaestro||'';}
