async function save(next,master=masterBase64){if(!canEdit)throw Error('Tu perfil solo permite consultar.');if(saving)throw Error('Hay un cambio guardándose. Espera e intenta de nuevo.');validateState(next);saving=true;try{const response=await fetch('/api/catalogo',{method:'PUT',headers:{'Content-Type':'application/json','X-CSRF-Token':currentUser.csrf},body:JSON.stringify({state:next,master,revision})});const result=await response.json();if(response.status===401){location.assign('/');throw Error('La sesión expiró.');}if(response.status===409){await load();invalidate();render();throw Error('Otro usuario actualizó el catálogo. Se cargaron los cambios; revisa e intenta de nuevo.');}if(!response.ok)throw Error(result.error||'No se pudo guardar.');state=validateState(result.state);masterBase64=result.master;revision=result.revision;purchaseFormat=result.formatoMaestro||'';invalidate();render();}finally{saving=false;}}
