$('buscar').oninput=render;$('filtro').onchange=render;
function fields(prefix=''){return {tipo:$(prefix?'editTipo':'tipo').value,categoria:$(prefix?'editCategoria':'categoria').value,subcategoria:$(prefix?'editSubcategoria':'subcategoria').value,nombre:$(prefix?'editNombre':'nombre').value.trim().replace(/\s+/g,' '),proveedor:$(prefix?'editProveedor':'proveedor').value.trim(),estado:prefix?$('editEstado').value:'ACTIVO'};}
