let userBranchChoices=[],userWarehouseChoices=[],userSelectedLocations=[];
function renderUserLocations(values=[]){const role=$('usuarioRol').value,restricted=['gerente','almacenista','requisicion'].includes(role),choices=['gerente','requisicion'].includes(role)?userBranchChoices:userWarehouseChoices;userSelectedLocations=role==='gerente'?[...userBranchChoices]:values.filter(v=>choices.includes(v));$('usuarioAccesos').hidden=!restricted;$('usuarioUbicaciones').replaceChildren();if(!restricted)return;$('usuarioAccesosTitulo').textContent=role==='gerente'?'Sucursales del gerente':role==='requisicion'?'Sucursales donde puede requisitar':'Almacenes que puede consultar';$('usuarioAccesosNota').textContent=role==='gerente'?'Administra las sucursales configuradas: crea requisiciones, carga maestros, modifica series y folios y autoriza cambios.':role==='requisicion'?'Marca al menos una sucursal. Solo podrá crear, consultar e imprimir sus propias solicitudes en esas sucursales y pedir correcciones autorizadas; no ve costos.':'Marca al menos un almacén. Solo podrá consultar requisiciones de los almacenes seleccionados. No podrá emitir solicitudes ni modificar datos.';for(const value of choices){const label=document.createElement('label'),input=document.createElement('input'),name=document.createElement('span');input.type='checkbox';input.checked=userSelectedLocations.includes(value);input.disabled=role==='gerente';input.setAttribute?.('aria-label','Acceso '+value);input.onchange=()=>{userSelectedLocations=input.checked?[...new Set([...userSelectedLocations,value])]:userSelectedLocations.filter(v=>v!==value);};name.textContent=value;label.append(input,name);$('usuarioUbicaciones').append(label);}}
function userLocationPayload(){const role=$('usuarioRol').value;if(role==='almacenista'&&!userSelectedLocations.length)throw Error('Selecciona al menos un almacén para el almacenista.');if(role==='requisicion'&&!userSelectedLocations.length)throw Error('Selecciona al menos una sucursal para Requisición.');return {sucursales:role==='gerente'?[...userBranchChoices]:role==='requisicion'?[...userSelectedLocations]:[],almacenes:role==='almacenista'?[...userSelectedLocations]:[]};}
