// Ventas conserva todos los SKU históricos; el sufijo identifica colisiones, no es un checksum.
const salesWrite=['superadmin','auxti','ventas','alta'].includes(currentUser.role),salesRead=currentUser.modulos.includes('ventas');
let ventas=null,ventasEditing=null,ventasPending=null,ventasDeleting=null,ventasSaving=false;
const salesAlphabet='0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';
function vKey(name){const words=norm(String(name).replace(/\d+(?:[.,]\d+)*/g,' ')).match(/[A-Z]+/g)||[];const letters=words.filter(w=>!['LA','LOS','EL','DEL'].includes(w)).map(w=>w[0]).join('').slice(0,7);if(!letters)throw Error('Escribe una descripción con palabras para generar la clave.');return letters.padEnd(7,'0');}
function vAssign(data,r){r.clave=r.clave||vKey(r.nombre);if(!/^[A-Z0-9]{7}$/.test(r.clave))throw Error('La clave debe tener 7 letras o números.');const body=r.tipo+r.categoria+r.subcategoria+r.clave,used=new Set([...data.state.reservados,...data.state.registros.map(x=>x.sku)]);const suffix=[...salesAlphabet].find(c=>!used.has(body+c));if(suffix===undefined)throw Error('Los 36 sufijos están ocupados. Cambia la clave de 7 caracteres.');return {...r,sku:body+suffix,digito:suffix};}
function vFields(){return {tipo:$('vTipo').value,categoria:$('vCategoria').value,subcategoria:$('vSubcategoria').value,nombre:$('vNombre').value.trim(),clave:norm($('vClave').value),estado:$('vEstado').value,modulo:$('vModulo').value};}
function vNew(data,fields){for(const key of ['tipo','categoria','subcategoria'])if(!fields[key]||fields[key]==='00')throw Error('Selecciona producto, categoría y subcategoría para generar un SKU nuevo.');if(!fields.nombre.trim())throw Error('Falta la descripción.');return vAssign(data,{...fields,id:data.state.maxId+1,anterior:'',validado:false,fila:null,editado:true,eliminado:false});}
function vSet(data){ventas=data;ventasPending=null;$('vGenerar').disabled=true;vRender();vPreview();}
async function vLoad(){const response=await fetch('/api/ventas',{cache:'no-store'}),data=await response.json();if(!response.ok)throw Error(data.error);vSet(data);}
async function vRequest(data,path='/api/ventas'){if(path.endsWith('importar')?!canLoadMasters:!salesWrite)throw Error('Tu perfil no permite esta operación.');if(ventasSaving)throw Error('Hay una operación de ventas en curso.');ventasSaving=true;try{const response=await fetch(path,{method:path.endsWith('importar')?'POST':'PUT',headers:{'Content-Type':'application/json','X-CSRF-Token':currentUser.csrf},body:JSON.stringify({...data,revision:ventas.revision})});const result=await response.json();if(response.status===409){await vLoad();throw Error('Otro usuario cambió ventas. Se actualizó el catálogo; revisa e intenta de nuevo.');}if(!response.ok)throw Error(result.error);vSet(result);return result;}finally{ventasSaving=false;}}
function vText(message){$('ventasMensaje').textContent=message;}
function vPreview(){if(!ventas)return;try{const fields=vFields(),old=ventas.state.registros.find(r=>r.id===ventasEditing);if(old?.validado){$('vPreview').textContent='SKU validado: '+old.sku+' · se conserva';return;}if(!fields.nombre){$('vPreview').textContent='El SKU aparecerá al escribir la descripción.';return;}const r=old&&fields.tipo===old.tipo&&fields.categoria===old.categoria&&fields.subcategoria===old.subcategoria&&fields.clave===old.clave?old:vNew(ventas,fields);$('vPreview').textContent='SKU propuesto: '+r.sku+' · longitud '+r.sku.length;}catch(err){$('vPreview').textContent=err.message;}}
