 for(const r of ventas.state.registros){const pending=[r.tipo,r.categoria,r.subcategoria].includes('00');if(filter==='activos'&&r.eliminado||filter==='borrados'&&!r.eliminado||filter==='revision'&&(!pending||r.eliminado))continue;if(q&&!norm([r.nombre,r.sku,r.anterior,c.TIP[r.tipo],c.CAT[r.categoria],c.SUB[r.subcategoria],r.originalCategoria,r.originalSubcategoria,r.modulo,c.PDV[r.modulo],r.originalModulo].join(' ')).includes(q))continue;shown++;const tr=document.createElement('tr');td(tr,String(r.id));td(tr,(r.sku||'PENDIENTE')+'\n'+(r.validado?'Validado · ':'Nuevo · ')+(r.clave||'—')+' / '+(r.digito||'—'));td(tr,r.nombre);td(tr,[c.TIP[r.tipo]||r.originalTipo||'POR REVISAR',c.CAT[r.categoria]||r.originalCategoria||'POR REVISAR',c.SUB[r.subcategoria]||r.originalSubcategoria||'POR REVISAR'].join(' / ')+(pending?'\nClasificación por revisar':''));td(tr,r.modulo+' · '+(c.PDV[r.modulo]||r.originalModulo||'SIN ASIGNAR')+' / '+(r.eliminado?'BAJA':r.estado));const actions=td(tr,'');if(salesWrite&&!r.eliminado){const edit=document.createElement('button');edit.className='secondary';edit.textContent='Editar';edit.onclick=()=>vEdit(r);actions.append(edit);if(canDelete){const del=document.createElement('button');del.className='danger';del.textContent='Dar de baja';del.onclick=()=>{ventasDeleting=r.id;$('vBajaNombre').textContent=r.nombre+' · '+r.sku;$('vBaja').showModal();};actions.append(del);}}$('vRegistros').append(tr);}
