function rwRenderLines(){$('rwPartidas').replaceChildren();for(const [i,line] of rwLines.entries()){const tr=document.createElement('tr');td(tr,(line.sku||'ID '+line.materialId)+' · '+line.nombre);const a=td(tr,''),quantity=document.createElement('input');quantity.type='number';quantity.min='0.000001';quantity.max='999999999';quantity.step='0.000001';quantity.required=true;quantity.value=line.cantidad;quantity.setAttribute('aria-label','Cantidad corregida '+line.nombre);quantity.oninput=()=>line.cantidad=quantity.value;a.append(quantity);td(tr,line.unidad);const b=td(tr,''),note=document.createElement('input');note.maxLength=500;note.value=line.observaciones;note.setAttribute('aria-label','Observación corregida '+line.nombre);note.oninput=()=>line.observaciones=note.value;b.append(note);const c=td(tr,''),del=document.createElement('button');del.type='button';del.className='secondary';del.textContent='Quitar material';del.onclick=()=>{rwLines.splice(i,1);rwRenderLines();};c.append(del);$('rwPartidas').append(tr);}}
async function rwStart(mode){try{if(!rqSelectedDoc||rqSelectedDoc.estado==='CANCELADA')return;if(!rqMaterials.length)rqMaterials=(await rqJSON('/materiales')).materiales;if(!rqMeta)rqApplyMeta(await rqJSON('/meta'));rwMode=mode;rwLines=rqSelectedDoc.partidas.map(r=>({...r}));$('rwCambioForm').hidden=false;$('rwCampos').hidden=mode!=='modificar';for(const field of $('rwCampos').querySelectorAll('input,select,textarea,button'))field.disabled=mode!=='modificar';$('rwCambioTitulo').textContent=(mode==='cancelar'?'Cancelar':mode==='aprobar'?'Aprobar requisición':'Corregir')+' '+rqSelectedDoc.numero;$('rwEnviar').textContent=rwCanManage?(mode==='cancelar'?'Confirmar cancelación':mode==='aprobar'?'Confirmar aprobación':'Aplicar corrección'):'Solicitar autorización';$('rwMotivo').value='';$('rwMotivo').required=mode!=='cancelar';$('rwCambioMensaje').textContent='';$('rwArea').replaceChildren();for(const area of rqMeta.areas)$('rwArea').add(new Option(area,area));if(!rqMeta.areas.includes(rqSelectedDoc.area))$('rwArea').add(new Option(rqSelectedDoc.area+' (área original)',rqSelectedDoc.area));$('rwArea').value=rqSelectedDoc.area;$('rwSolicitante').value=rqSelectedDoc.solicitante;$('rwObservaciones').value=rqSelectedDoc.observaciones;$('rwMaterial').replaceChildren();for(const r of rqMaterials.filter(r=>r.estado==='ACTIVO'&&r.unidad))$('rwMaterial').add(new Option((r.sku||'ID '+r.id)+' · '+r.nombre,r.id));rwRenderLines();$('rwCambioForm').scrollIntoView({block:'start'});}catch(err){rqMessage(err.message);}}
