$('rwAgregar').onclick=()=>{const material=rqMaterials.find(r=>String(r.id)===$('rwMaterial').value);if(!material)return;if(rwLines.some(r=>r.materialId===material.id)){$('rwCambioMensaje').textContent='El material ya está incluido; corrige su cantidad.';return;}if(rwLines.length>=200){$('rwCambioMensaje').textContent='Máximo 200 partidas.';return;}rwLines.push({materialId:material.id,sku:material.sku,nombre:material.nombre,unidad:material.unidad,cantidad:'1',observaciones:''});rwRenderLines();};
