async function rwLoad(){const result=await rqJSON('/cambios');rwRows=result.cambios;$('rwTabla').replaceChildren();for(const c of rwRows){const tr=document.createElement('tr');td(tr,jmDate(c.fecha)+' · '+c.estado);td(tr,(c.folio||c.objetivo)+' · '+c.sucursal);td(tr,c.tipo+' · '+c.solicitadoPor);td(tr,c.motivo+(c.resueltoPor?' · '+c.resueltoPor+' · '+c.comentario:''));const cell=td(tr,''),button=document.createElement('button');button.className='secondary';button.textContent=c.estado==='PENDIENTE'&&rwCanManage?'Revisar autorización':'Ver propuesta';button.onclick=()=>rwReview(c);cell.append(button);$('rwTabla').append(tr);}$('rwMensaje').textContent=rwRows.filter(c=>c.estado==='PENDIENTE').length+' pendientes · '+rwRows.length+' movimientos visibles (hasta 500).';}
