async function rwDecide(approved){if(rwSending)return;if(approved&&rwSelectedChange?.tipo==='aprobar'){const doc=await rqJSON('/'+rwSelectedChange.objetivo);$('rwRevision').close();rqShowDocument(doc);await rwStartDelivery('surtir');return;}if(!$('rwResolverForm').reportValidity())return;rwSending=true;$('rwAprobar').disabled=$('rwRechazar').disabled=true;try{await rqJSON('/cambios/'+rwSelectedChange.id+'/resolver',{method:'POST',body:JSON.stringify({aprobar:approved,comentario:$('rwComentario').value,autorizarNegativo:$('rwNegativo').checked})});$('rwRevision').close();await rwLoad();if(approved){rwInvalidateReport();void rqRefreshAfterSave();}}catch(err){$('rwRevisionMensaje').textContent=err.message;}finally{rwSending=false;$('rwAprobar').disabled=$('rwRechazar').disabled=false;}}
