let cpPending=null,cpRunning=false;
async function cpRequest(data){const response=await fetch('/api/compras/importar',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':currentUser.csrf},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw Error(result.error||'No se pudo actualizar el maestro.');return result;}
function cpClear(){cpPending=null;$('cpRevision').hidden=true;$('maestroArchivo').value='';}
$('maestroArchivo').onchange=async e=>{const file=e.target.files[0];cpPending=null;$('cpRevision').hidden=true;if(!file)return;if(file.size>15*1024*1024){$('maestroMensaje').textContent='Máximo 15 MB por maestro.';return;}cpRunning=true;$('maestroArchivo').disabled=true;$('maestroMensaje').textContent='Revisando PRODUCTOS en el servidor…';try{const pending={archivo:file.name,contenido:bytesBase64(new Uint8Array(await file.arrayBuffer())),revision,revisar:true};const result=await cpRequest(pending);cpPending={...pending,revision:result.revision,revisar:false};const s=result.resumen;$('cpResumen').replaceChildren();for(const [title,value] of [['Productos leídos',s.total],['Nuevos',s.agregados],['Actualizados',s.actualizados],['Sin cambios',s.sinCambios],['SKU que cambiarán',s.skuActualizados],['Filas por revisar',s.omitidos]]){const div=document.createElement('div');div.className='rp-kpi';const label=document.createElement('p'),strong=document.createElement('strong');label.textContent=title;strong.textContent=value;div.append(label,strong);$('cpResumen').append(div);}$('cpCambios').replaceChildren();for(const item of s.cambiosSKU){const tr=document.createElement('tr');for(const value of [item.descripcion,item.anterior,item.nuevo])td(tr,value);$('cpCambios').append(tr);}for(const item of s.conflictos){const tr=document.createElement('tr');for(const value of ['Fila '+item.fila+' · '+item.descripcion,'—',item.motivo])td(tr,value);$('cpCambios').append(tr);}$('cpRevision').hidden=false;$('maestroMensaje').textContent='Revisión lista en '+s.segundos+' s. Confirma para actualizar. Las filas indicadas como ambiguas se omitirán.';}catch(err){$('maestroMensaje').textContent=err.message;}finally{cpRunning=false;$('maestroArchivo').disabled=false;}};
$('cpCancelar').onclick=()=>{cpClear();$('maestroMensaje').textContent='Archivo descartado. No se modificaron los datos.';};
$('cpConfirmar').onclick=async()=>{if(cpRunning||!cpPending)return;cpRunning=true;$('cpConfirmar').disabled=true;$('maestroMensaje').textContent='Actualizando el catálogo…';try{const result=await cpRequest(cpPending),s=result.resumen;cpClear();await load();invalidate();render();$('maestroMensaje').textContent='Actualización completada: '+s.agregados+' nuevos, '+s.actualizados+' actualizados, '+s.skuActualizados+' SKU cambiados y '+s.omitidos+' filas omitidas. Proceso del servidor: '+s.segundos+' s.';}catch(err){$('maestroMensaje').textContent=err.message;}finally{cpRunning=false;$('cpConfirmar').disabled=false;}};
