const rqBeforePurchase=rqShowDocument;rqShowDocument=function(doc){rqBeforePurchase(doc);const box=document.createElement('section');box.id='rqPurchaseLinks';const title=document.createElement('h3');title.textContent='Pedidos de compra vinculados';box.append(title);$('rqDetalleDatos').append(box);if(currentUser.modulos.includes('inventarios')){const delivery=document.createElement('a');delivery.className='btn';delivery.href='/inventarios?'+new URLSearchParams({entregar:doc.id,sucursal:doc.sucursal});delivery.textContent='Entregar a Compras';box.append(delivery);}if(currentUser.modulos.includes('pedidoscompra')&&['compras','gerente'].includes(currentUser.role)&&doc.estado!=='CANCELADO'){const create=document.createElement('a');create.href='/compras?requisicion='+doc.id;create.textContent='Generar pedido de compra desde esta requisición';create.className='btn';box.append(create);}fetch('/api/requisiciones/'+doc.id+'/pedidos-compra',{cache:'no-store'}).then(async r=>{if(!r.ok)return;const data=await r.json();if(rqSelectedDoc?.id!==doc.id)return;for(const order of data.pedidos){const p=document.createElement('p');p.textContent=order.folio+' · '+order.estado+' · '+order.sucursal;box.append(p);if(currentUser.modulos.includes('pedidoscompra')){const a=document.createElement('a');a.href='/compras?pedido='+order.id;a.textContent='Ver pedido';box.append(a);}}if(!data.pedidos.length){const p=document.createElement('p');p.textContent='Sin pedidos de compra vinculados.';box.append(p);}}).catch(()=>{});};

