const skuConfigDialog=document.createElement('dialog');skuConfigDialog.className='jm-catalog-config';skuConfigDialog.innerHTML='<h2>Clasificaciones SKU</h2><p>Configura tus propios tipos, categorías, subcategorías y agrupaciones PDV.</p><form id="skuConfigForm" class="grid"><label>Grupo<select id="skuConfigGroup"></select></label><label>Código<input id="skuConfigCode" required minlength="2" maxlength="3"></label><label>Nombre<input id="skuConfigName" required maxlength="160"></label><div class="actions"><button>Guardar clasificación</button><button type="button" id="skuConfigNew" class="secondary">Nueva</button><button type="button" id="skuConfigClose" class="secondary">Cerrar</button></div></form><output id="skuConfigMessage" role="status"></output><div class="scroll"><table><thead><tr><th>Grupo</th><th>Código</th><th>Nombre</th><th></th></tr></thead><tbody id="skuConfigRows"></tbody></table></div>';
document.body.append(skuConfigDialog);let skuConfigScope='compras',skuConfigEditing=null;
async function skuConfigApi(path,data){const response=await fetch(path,{method:data?'POST':'GET',headers:{'Content-Type':'application/json',...(data?{'X-CSRF-Token':currentUser.csrf}:{})},...(data?{body:JSON.stringify(data)}:{})});const value=await response.json();if(!response.ok)throw Error(value.error);return value;}
function skuConfigReset(){skuConfigEditing=null;$('skuConfigCode').disabled=false;$('skuConfigGroup').disabled=false;$('skuConfigCode').value='';$('skuConfigName').value='';}
function skuPopulate(select,values,optional=false){const old=select.value;select.replaceChildren();for(const [code,name]of Object.entries(values))select.add(new Option(code+' · '+name,code));if(optional)select.add(new Option('000 · Sin agrupación PDV','000'));if(!select.options.length){select.add(new Option('Configura primero este catálogo',''));select.disabled=true;}else{select.disabled=false;if([...select.options].some(o=>o.value===old))select.value=old;}}
async function skuRefreshClassifications(){const data=await skuConfigApi('/api/me');for(const [target,key,id] of [[TIP,'TIP','tipo'],[CAT,'CAT','categoria'],[SUB,'SUB','subcategoria']]){for(const code of Object.keys(target))delete target[code];Object.assign(target,data.catalogos.compras[key]);skuPopulate($(id),target);}const emptyPurchase=[TIP,CAT,SUB].some(v=>!Object.keys(v).length);$('nuevo').querySelector('button').disabled=emptyPurchase;if(ventas){ventas.catalogos=data.catalogos.ventas;for(const [id,key]of [['vTipo','TIP'],['vCategoria','CAT'],['vSubcategoria','SUB'],['vModulo','PDV']])skuPopulate($(id),ventas.catalogos[key],key==='PDV');$('vGuardar').disabled=['TIP','CAT','SUB'].some(key=>!Object.keys(ventas.catalogos[key]).length);vPreview();}}
async function skuConfigLoad(){const value=await skuConfigApi('/api/empresa/taxonomia');$('skuConfigRows').replaceChildren();for(const item of value.clasificaciones.filter(v=>v.ambito===skuConfigScope)){const tr=document.createElement('tr');for(const value of [item.grupo,item.codigo,item.nombre]){const td=document.createElement('td');td.textContent=value;tr.append(td);}const td=document.createElement('td'),button=document.createElement('button');button.type='button';button.className='secondary';button.textContent='Editar nombre';button.onclick=()=>{skuConfigEditing=item;$('skuConfigGroup').value=item.grupo;$('skuConfigCode').value=item.codigo;$('skuConfigName').value=item.nombre;$('skuConfigGroup').disabled=true;$('skuConfigCode').disabled=true;};td.append(button);tr.append(td);$('skuConfigRows').append(tr);}await skuRefreshClassifications();}
for(const [scope,id]of [['compras','nuevo'],['ventas','ventasForm']]){const toolbar=document.createElement('div');toolbar.className='actions';const text=document.createElement('p');text.className='note';text.textContent='Los campos de clasificación se administran en el catálogo de '+scope+'.';toolbar.append(text);if(currentUser.role==='superadmin'){const button=document.createElement('button');button.type='button';button.className='secondary';button.textContent='Agregar / editar clasificaciones';button.onclick=async()=>{skuConfigScope=scope;skuConfigReset();$('skuConfigGroup').replaceChildren();for(const [key,title]of [['TIP','Producto / tipo'],['CAT','Categoría'],['SUB','Subcategoría'],...(scope==='ventas'?[['PDV','Agrupación PDV']]:[])])$('skuConfigGroup').add(new Option(title,key));skuConfigDialog.showModal();try{await skuConfigLoad();}catch(e){$('skuConfigMessage').textContent=e.message;}};toolbar.append(button);}else text.textContent+=' Solicita a Sistemas las altas o cambios.';$(id).before(toolbar);}
$('skuConfigForm').onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{await skuConfigApi('/api/empresa/taxonomia',{ambito:skuConfigScope,grupo:$('skuConfigGroup').value,codigo:$('skuConfigCode').value,nombre:$('skuConfigName').value,revision:skuConfigEditing?.revision||0});skuConfigReset();await skuConfigLoad();$('skuConfigMessage').textContent='Clasificación guardada y listas actualizadas.';}catch(e){$('skuConfigMessage').textContent=e.message;}finally{button.disabled=false;}};$('skuConfigClose').onclick=()=>skuConfigDialog.close();$('skuConfigNew').onclick=skuConfigReset;
const skuSalesInit=salesInit;salesInit=async()=>{await skuSalesInit();await skuRefreshClassifications();};try{await skuRefreshClassifications();}catch(e){message(e);}
